package ru.neverland.townysieges;
import java.util.*;
import java.nio.file.*;
import java.io.IOException;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.configuration.ConfigurationSection;
import ru.neverland.core.*;

/** Cargo credit and its receipt, or physical consumption and paid minute, commit together. */
public final class CampSupplyLedger {
    public record Receipt(UUID town,UUID camp,Map<String,Long> cargo){public Receipt{Objects.requireNonNull(town);Objects.requireNonNull(camp);cargo=items(cargo);}}
    public record Funding(UUID war,UUID town,long minute,String source,String state,Map<String,Long> cost){public Funding{Objects.requireNonNull(war);Objects.requireNonNull(town);if(minute<0||!Set.of("ARMY","CARGO").contains(source)||!Set.of("PLANNED","PAID").contains(state))throw new IllegalArgumentException("Неверная квитанция снабжения");cost=Map.copyOf(cost);if(cost.isEmpty()||cost.values().stream().anyMatch(n->n==null||n<=0||n>1_000_000_000_000L))throw new IllegalArgumentException("Неверный расход лагеря");}public UUID id(){return UUID.nameUUIDFromBytes(("raid-supplies:"+war+":"+minute).getBytes(java.nio.charset.StandardCharsets.UTF_8));}public Funding paid(){return new Funding(war,town,minute,source,"PAID",cost);}}
    public record State(Map<UUID,Map<String,Long>> stock,Map<UUID,Receipt> receipts,Map<UUID,Funding> funding){public State{var copy=new HashMap<UUID,Map<String,Long>>();stock.forEach((id,m)->copy.put(id,items(m)));stock=Map.copyOf(copy);receipts=Map.copyOf(receipts);funding=Map.copyOf(funding);funding.forEach((id,f)->{if(!id.equals(f.war()))throw new IllegalArgumentException("Квитанция другой войны");});}public static State empty(){return new State(Map.of(),Map.of(),Map.of());}}
    private final Path file;private State state=State.empty();private boolean ready;
    public CampSupplyLedger(Path file)throws IOException{this.file=file;load();}
    public State state(){return state;}public boolean writable(){return ready&&AtomicFiles.writable(file);}
    public static Map<String,Long> items(Map<String,Long> input){var result=new HashMap<String,Long>();long slots=0;for(var e:input.entrySet()){long n=e.getValue();if(!Set.of("BREAD","IRON_INGOT").contains(e.getKey())||n<0||n>3456)throw new IllegalArgumentException("Разрешены хлеб и железные слитки, не более 54 стопок");if(n>0){slots+=(n+63)/64;result.put(e.getKey(),n);}}if(slots>54)throw new IllegalArgumentException("Военный склад лагеря заполнен");return Map.copyOf(result);}
    private static Map<String,Long> map(ConfigurationSection s){var out=new HashMap<String,Long>();if(s!=null)for(String k:s.getKeys(false)){if(!(s.get(k) instanceof Number))throw new IllegalArgumentException("Повреждён запас");out.put(k,SafeYaml.longValue(s,k));}return Map.copyOf(out);}
    private void load()throws IOException{try{YamlConfiguration y=SafeYaml.load(file);if(y.contains("schema")&&SafeYaml.intValue(y,"schema")!=1)throw new IOException("Неизвестная схема склада лагеря");var stock=new HashMap<UUID,Map<String,Long>>();var receipts=new HashMap<UUID,Receipt>();var funds=new HashMap<UUID,Funding>();var s=y.getConfigurationSection("stock");if(s!=null)for(String id:s.getKeys(false))stock.put(UUID.fromString(id),map(s.getConfigurationSection(id)));s=y.getConfigurationSection("receipts");if(s!=null)for(String id:s.getKeys(false)){var v=s.getConfigurationSection(id);receipts.put(UUID.fromString(id),new Receipt(UUID.fromString(SafeYaml.text(v,"town")),UUID.fromString(SafeYaml.text(v,"camp")),map(v.getConfigurationSection("cargo"))));}s=y.getConfigurationSection("funding");if(s!=null)for(String id:s.getKeys(false)){var v=s.getConfigurationSection(id);UUID war=UUID.fromString(id);funds.put(war,new Funding(war,UUID.fromString(SafeYaml.text(v,"town")),SafeYaml.longValue(v,"minute"),SafeYaml.text(v,"source"),SafeYaml.text(v,"state"),map(v.getConfigurationSection("cost"))));}state=new State(stock,receipts,funds);AtomicFiles.loaded(file);ready=true;}catch(Exception ex){throw new IOException("Не удалось загрузить снабжение лагерей",ex);}}
    public void save(State next)throws IOException{if(!writable())throw new IOException("Снабжение лагеря временно недоступно");var y=new YamlConfiguration();y.set("schema",1);next.stock().forEach((id,m)->y.createSection("stock."+id,m));next.receipts().forEach((id,r)->{String p="receipts."+id;y.set(p+".town",r.town().toString());y.set(p+".camp",r.camp().toString());y.createSection(p+".cargo",r.cargo());});next.funding().forEach((id,f)->{String p="funding."+id;y.set(p+".town",f.town().toString());y.set(p+".minute",f.minute());y.set(p+".source",f.source());y.set(p+".state",f.state());y.createSection(p+".cost",f.cost());});AtomicFiles.write(file,y::saveToString);state=next;}
    public boolean receive(UUID shipment,Receipt receipt)throws IOException{Receipt old=state.receipts().get(shipment);if(old!=null){if(!old.equals(receipt))throw new IllegalArgumentException("Груз повторной поставки изменился");return true;}var inventory=new HashMap<>(state.stock().getOrDefault(receipt.town(),Map.of()));receipt.cargo().forEach((m,n)->inventory.merge(m,n,Math::addExact));try{items(inventory);}catch(IllegalArgumentException full){return false;}var stock=new HashMap<>(state.stock());stock.put(receipt.town(),inventory);var receipts=new HashMap<>(state.receipts());receipts.put(shipment,receipt);save(new State(stock,receipts,state.funding()));return true;}
    public static boolean covers(Map<String,Long> stock,Map<String,Long> cost){return cost.entrySet().stream().allMatch(e->stock.getOrDefault(e.getKey(),0L)>=e.getValue());}
    public void funding(Funding f,boolean consume)throws IOException{var old=state.funding().get(f.war());if(old!=null){if(old.equals(f))return;if(!old.town().equals(f.town())||f.minute()<old.minute()||old.minute()==f.minute()&&(old.state().equals("PAID")||!old.source().equals(f.source())||!old.cost().equals(f.cost()))||f.minute()>old.minute()&&old.state().equals("PLANNED"))throw new IllegalArgumentException("Сначала завершите сохранённый расход лагеря");}var stock=new HashMap<>(state.stock());if(consume){var inventory=new HashMap<>(stock.getOrDefault(f.town(),Map.of()));if(!covers(inventory,f.cost()))throw new IllegalArgumentException("В лагере не хватает запасов");f.cost().forEach((m,n)->inventory.put(m,inventory.get(m)-n));stock.put(f.town(),inventory);}var funds=new HashMap<>(state.funding());funds.put(f.war(),f);save(new State(stock,state.receipts(),funds));}
    public void clear(UUID war)throws IOException{var funds=new HashMap<>(state.funding());funds.remove(war);save(new State(state.stock(),state.receipts(),funds));}
}
